insert into public.course_lessons (id, subject_id, sort_order, title, steps)
values
  ($q$gh01$q$, $q$greetings-hello$q$, 0, $q$Hello!$q$, $j$[{"id":"rule-1","type":"rule","title":"Polite particles","body":"Thai has polite words added to the end of a question, response, or statement: khráp for men; for women, khâ after statements and answers and khá after questions. They make it sound more polite. They are used with people older than you, or whenever you want to sound polite — for example, when first meeting someone.","source":"Essential Thai (Higbie), p.22"},{"id":"wi-2","type":"wordIntro","word":{"thai":"สวัสดี","roman":"sà-wàt-dii","english":"hello"},"source":"Essential Thai (Higbie), p.22"},{"id":"wi-3","type":"wordIntro","word":{"thai":"ค่ะ","roman":"khâ","english":"polite particle (said by women)"},"source":"Essential Thai (Higbie), p.22"},{"id":"mc-5","type":"translationChoice","thai":"สวัสดีค่ะ","roman":"sà-wàt-dii khâ","options":[{"text":"Good luck.","correct":false},{"text":"Hello. (said by a woman)","correct":true},{"text":"Excuse me.","correct":false},{"text":"Thank you.","correct":false}],"source":"Essential Thai (Higbie), p.22","parts":["สวัสดี","ค่ะ"]},{"id":"sp-7","type":"speak","thai":"สวัสดีค่ะ","roman":"sà-wàt-dii khâ","meaning":"Hello. (said by a woman)","source":"Essential Thai (Higbie), p.22","parts":["สวัสดี","ค่ะ"]},{"id":"so-9","type":"sentenceOrder","prompt":"Hello. (said by a woman)","tileUnit":"word","words":{"a":{"roman":"sà-wàt-dii","thai":"สวัสดี"},"b":{"roman":"khâ","thai":"ค่ะ"}},"poolOrder":["b","a"],"correctOrder":["a","b"],"source":"Essential Thai (Higbie), p.22"},{"id":"mc-11","type":"translationChoice","thai":"ค่ะ","roman":"khâ","options":[{"text":"Polite particle (said by a man).","correct":false},{"text":"Thank you.","correct":false},{"text":"Polite particle (said by a woman).","correct":true},{"text":"Hello.","correct":false}],"source":"Essential Thai (Higbie), p.22","parts":["ค่ะ"]},{"id":"wi-4","type":"wordIntro","word":{"thai":"ครับ","roman":"khráp","english":"polite particle (said by men)"},"source":"Essential Thai (Higbie), p.22"},{"id":"rp-6","type":"reply","context":[{"speaker":"M","thai":"สวัสดีครับ","parts":["สวัสดี","ครับ"],"roman":"sà-wàt-dii khráp","english":"Hello. (said by a man)"}],"replySpeaker":"F","thai":"สวัสดีค่ะ","roman":"sà-wàt-dii khâ","english":"Hello. (said by a woman)","options":[{"thai":"สวัสดีครับ","roman":"sà-wàt-dii khráp","correct":false},{"thai":"สวัสดีค่ะ","roman":"sà-wàt-dii khâ","correct":true},{"thai":"ครับ","roman":"khráp","correct":false}],"source":"Essential Thai (Higbie), p.22","parts":["สวัสดี","ค่ะ"]},{"id":"mc-8","type":"translationChoice","thai":"สวัสดีครับ","roman":"sà-wàt-dii khráp","options":[{"text":"How are you?","correct":false},{"text":"Thank you.","correct":false},{"text":"Good luck.","correct":false},{"text":"Hello. (said by a man)","correct":true}],"source":"Essential Thai (Higbie), p.22","parts":["สวัสดี","ครับ"]},{"id":"sp-10","type":"speak","thai":"สวัสดีครับ","roman":"sà-wàt-dii khráp","meaning":"Hello. (said by a man)","source":"Essential Thai (Higbie), p.22","parts":["สวัสดี","ครับ"]},{"id":"mc-12","type":"translationChoice","thai":"ครับ","roman":"khráp","options":[{"text":"Polite particle (said by a man).","correct":true},{"text":"Polite particle (said by a woman).","correct":false},{"text":"Thank you.","correct":false},{"text":"Hello.","correct":false}],"source":"Essential Thai (Higbie), p.22","parts":["ครับ"]},{"id":"wi-13","type":"wordIntro","word":{"thai":"ไป","roman":"pai","english":"go"},"source":"Essential Thai (Higbie), p.22"},{"id":"wi-14","type":"wordIntro","word":{"thai":"ไหน","roman":"nǎi","english":"where"},"source":"Essential Thai (Higbie), p.22"},{"id":"mc-15","type":"translationChoice","thai":"ไปไหน","roman":"pai nǎi","options":[{"text":"Hello.","correct":false},{"text":"Where are you going?","correct":true},{"text":"What's your name?","correct":false},{"text":"Good luck.","correct":false}],"source":"Essential Thai (Higbie), p.22","parts":["ไป","ไหน"]},{"id":"so-16","type":"sentenceOrder","prompt":"Where are you going?","tileUnit":"word","words":{"a":{"roman":"pai","thai":"ไป"},"b":{"roman":"nǎi","thai":"ไหน"},"x0":{"thai":"ครับ","roman":"khráp"},"x1":{"thai":"สวัสดี","roman":"sà-wàt-dii"}},"poolOrder":["x0","b","a","x1"],"correctOrder":["a","b"],"source":"Essential Thai (Higbie), p.22"},{"id":"match-17","type":"match","pairs":[{"thai":"สวัสดี","roman":"sà-wàt-dii","english":"hello"},{"thai":"ค่ะ","roman":"khâ","english":"polite particle (said by women)"},{"thai":"ครับ","roman":"khráp","english":"polite particle (said by men)"},{"thai":"ไป","roman":"pai","english":"go"},{"thai":"ไหน","roman":"nǎi","english":"where"}],"source":"Essential Thai (Higbie), p.22"}]$j$::jsonb),
  ($q$gh02$q$, $q$greetings-hello$q$, 1, $q$Where are you going?$q$, $j$[{"id":"rule-18","type":"rule","title":"Saying \"I\"","body":"Everyday Thai often leaves out \"I\" when it's obvious — pai hǎa phɯ̂an on its own means \"going to see a friend\". While you learn, say it: phǒm if you're a man, chán if you're a woman. phǒm pai hǎa phɯ̂an is \"I'm going to see a friend.\"","source":"Essential Thai (Higbie), p.38"},{"id":"rp-24","type":"reply","context":[{"speaker":"M","thai":"สวัสดีครับ","parts":["สวัสดี","ครับ"],"roman":"sà-wàt-dii khráp","english":"Hello. (said by a man)"},{"speaker":"F","thai":"สวัสดีค่ะ","parts":["สวัสดี","ค่ะ"],"roman":"sà-wàt-dii khâ","english":"Hello. (said by a woman)"}],"replySpeaker":"M","thai":"ไปไหน","roman":"pai nǎi","english":"Where are you going?","options":[{"thai":"ค่ะ","roman":"khâ","correct":false},{"thai":"ไปไหน","roman":"pai nǎi","correct":true},{"thai":"ครับ","roman":"khráp","correct":false},{"thai":"สวัสดีครับ","roman":"sà-wàt-dii khráp","correct":false}],"source":"Essential Thai (Higbie), p.22","parts":["ไป","ไหน"]},{"id":"sp-26","type":"speak","thai":"ไปไหน","roman":"pai nǎi","meaning":"Where are you going?","source":"Essential Thai (Higbie), p.22","parts":["ไป","ไหน"]},{"id":"mc-33","type":"translationChoice","thai":"สวัสดีครับ","roman":"sà-wàt-dii khráp","options":[{"text":"Hello. (said by a man)","correct":true},{"text":"Thank you.","correct":false},{"text":"Where are you going?","correct":false},{"text":"I'm going out.","correct":false}],"source":"Essential Thai (Higbie), p.22","parts":["สวัสดี","ครับ"]},{"id":"so-34","type":"sentenceOrder","prompt":"Hello. (said by a woman)","tileUnit":"word","words":{"a":{"roman":"sà-wàt-dii","thai":"สวัสดี"},"b":{"roman":"khâ","thai":"ค่ะ"},"x0":{"thai":"ไป","roman":"pai"},"x1":{"thai":"ครับ","roman":"khráp"}},"poolOrder":["b","x1","x0","a"],"correctOrder":["a","b"],"source":"Essential Thai (Higbie), p.22"},{"id":"wi-19","type":"wordIntro","word":{"thai":"ผม","roman":"phǒm","english":"I (said by a man)"},"source":"Essential Thai (Higbie), p.38"},{"id":"wi-20","type":"wordIntro","word":{"thai":"ฉัน","roman":"chán","english":"I (said by a woman)"},"source":"Essential Thai (Higbie), p.38"},{"id":"wi-21","type":"wordIntro","word":{"thai":"เที่ยว","roman":"thîao","english":"go out / travel around"},"source":"Essential Thai (Higbie), p.22"},{"id":"so-25","type":"sentenceOrder","prompt":"I'm going out/traveling around. (said by a man)","tileUnit":"word","words":{"a":{"roman":"pai","thai":"ไป"},"b":{"roman":"thîao","thai":"เที่ยว"},"x0":{"thai":"สวัสดี","roman":"sà-wàt-dii"},"x1":{"thai":"ผม","roman":"phǒm"},"subj":{"thai":"ผม","roman":"phǒm"}},"poolOrder":["x0","x1","subj","b","a"],"correctOrder":["subj","a","b"],"source":"Essential Thai (Higbie), p.22"},{"id":"mc-27","type":"translationChoice","thai":"ฉันไปเที่ยว","roman":"chán pai thîao","options":[{"text":"Hello.","correct":false},{"text":"Thank you.","correct":false},{"text":"I'm going out/traveling around.","correct":true},{"text":"Where are you going?","correct":false}],"source":"Essential Thai (Higbie), p.22","parts":["ฉัน","ไป","เที่ยว"]},{"id":"sp-28","type":"speak","thai":"ผมไปเที่ยว","roman":"phǒm pai thîao","meaning":"I'm going out/traveling around.","source":"Essential Thai (Higbie), p.22","parts":["ผม","ไป","เที่ยว"]},{"id":"rp-32","type":"reply","context":[{"speaker":"M","thai":"สวัสดีครับ","parts":["สวัสดี","ครับ"],"roman":"sà-wàt-dii khráp","english":"Hello. (said by a man)"},{"speaker":"F","thai":"สวัสดีค่ะ","parts":["สวัสดี","ค่ะ"],"roman":"sà-wàt-dii khâ","english":"Hello. (said by a woman)"},{"speaker":"M","thai":"ไปไหน","parts":["ไป","ไหน"],"roman":"pai nǎi","english":"Where are you going?"}],"replySpeaker":"F","thai":"ฉันไปเที่ยว","roman":"chán pai thîao","english":"I'm going out/traveling around.","options":[{"thai":"ฉันไปเที่ยว","roman":"chán pai thîao","correct":true},{"thai":"สวัสดีค่ะ","roman":"sà-wàt-dii khâ","correct":false},{"thai":"ครับ","roman":"khráp","correct":false}],"source":"Essential Thai (Higbie), p.22","parts":["ฉัน","ไป","เที่ยว"]},{"id":"mc-35","type":"translationChoice","thai":"เที่ยว","roman":"thîao","options":[{"text":"go out / travel around","correct":true},{"text":"where","correct":false},{"text":"hello","correct":false},{"text":"go","correct":false}],"source":"Essential Thai (Higbie), p.22","parts":["เที่ยว"]},{"id":"wi-22","type":"wordIntro","word":{"thai":"หา","roman":"hǎa","english":"look for / see (someone)"},"source":"Essential Thai (Higbie), p.22"},{"id":"mc-36","type":"translationChoice","thai":"หา","roman":"hǎa","options":[{"text":"look for / see (someone)","correct":true},{"text":"go","correct":false},{"text":"friend","correct":false},{"text":"go out / travel around","correct":false}],"source":"Essential Thai (Higbie), p.22","parts":["หา"]},{"id":"wi-23","type":"wordIntro","word":{"thai":"เพื่อน","roman":"phɯ̂an","english":"friend"},"source":"Essential Thai (Higbie), p.22"},{"id":"so-29","type":"sentenceOrder","prompt":"I'm going to see a friend. (said by a woman)","tileUnit":"word","words":{"a":{"roman":"pai","thai":"ไป"},"b":{"roman":"hǎa","thai":"หา"},"c":{"roman":"phɯ̂an","thai":"เพื่อน"},"x0":{"thai":"ไหน","roman":"nǎi"},"x1":{"thai":"ครับ","roman":"khráp"},"subj":{"thai":"ฉัน","roman":"chán"}},"poolOrder":["b","x1","c","subj","a","x0"],"correctOrder":["subj","a","b","c"],"source":"Essential Thai (Higbie), p.22"},{"id":"mc-30","type":"translationChoice","thai":"ผมไปหาเพื่อน","roman":"phǒm pai hǎa phɯ̂an","options":[{"text":"I'm going to see a friend.","correct":true},{"text":"I'm going out/traveling around.","correct":false},{"text":"Where are you going?","correct":false},{"text":"Hello.","correct":false}],"source":"Essential Thai (Higbie), p.22","parts":["ผม","ไป","หา","เพื่อน"]},{"id":"sp-31","type":"speak","thai":"ฉันไปหาเพื่อน","roman":"chán pai hǎa phɯ̂an","meaning":"I'm going to see a friend.","source":"Essential Thai (Higbie), p.22","parts":["ฉัน","ไป","หา","เพื่อน"]},{"id":"mc-37","type":"translationChoice","thai":"เพื่อน","roman":"phɯ̂an","options":[{"text":"home","correct":false},{"text":"friend","correct":true},{"text":"go out / travel around","correct":false},{"text":"look for / see (someone)","correct":false}],"source":"Essential Thai (Higbie), p.22","parts":["เพื่อน"]},{"id":"match-38","type":"match","pairs":[{"thai":"ผม","roman":"phǒm","english":"I (said by a man)"},{"thai":"ฉัน","roman":"chán","english":"I (said by a woman)"},{"thai":"เที่ยว","roman":"thîao","english":"go out / travel around"},{"thai":"หา","roman":"hǎa","english":"look for / see (someone)"},{"thai":"เพื่อน","roman":"phɯ̂an","english":"friend"}],"source":"Essential Thai (Higbie), p.38"}]$j$::jsonb),
  ($q$gh03$q$, $q$greetings-hello$q$, 2, $q$Good, or not?$q$, $j$[{"id":"rule-39","type":"rule","title":"Yes/no questions with mái","body":"To make a simple question like \"is it good?\", put mái (high tone) after the word. Answer \"yes\" by repeating the word, or \"no\" by putting mâi (falling tone) before it.","source":"Essential Thai (Higbie), p.23"},{"id":"wi-40","type":"wordIntro","word":{"thai":"ดี","roman":"dii","english":"good"},"source":"Essential Thai (Higbie), p.23"},{"id":"mc-50","type":"translationChoice","thai":"ดี","roman":"dii","options":[{"text":"question particle: is it ___?","correct":false},{"text":"not / no","correct":false},{"text":"good","correct":true},{"text":"hello","correct":false}],"source":"Essential Thai (Higbie), p.23","parts":["ดี"]},{"id":"wi-41","type":"wordIntro","word":{"thai":"มั้ย","roman":"mái","english":"question particle: is it ___?"},"source":"Essential Thai (Higbie), p.23"},{"id":"mc-42","type":"translationChoice","thai":"ดีมั้ย","roman":"dii mái","options":[{"text":"Hello.","correct":false},{"text":"Is it fun?","correct":false},{"text":"Where are you going?","correct":false},{"text":"Is it good?","correct":true}],"source":"Essential Thai (Higbie), p.23","parts":["ดี","มั้ย"]},{"id":"so-43","type":"sentenceOrder","prompt":"Is it good?","tileUnit":"word","words":{"a":{"roman":"dii","thai":"ดี"},"b":{"roman":"mái","thai":"มั้ย"},"x0":{"thai":"ค่ะ","roman":"khâ"},"x1":{"thai":"ครับ","roman":"khráp"}},"poolOrder":["a","x1","b","x0"],"correctOrder":["a","b"],"source":"Essential Thai (Higbie), p.23"},{"id":"sp-44","type":"speak","thai":"ดีมั้ย","roman":"dii mái","meaning":"Is it good?","source":"Essential Thai (Higbie), p.23","parts":["ดี","มั้ย"]},{"id":"wi-45","type":"wordIntro","word":{"thai":"ไม่","roman":"mâi","english":"not / no"},"source":"Essential Thai (Higbie), p.23"},{"id":"mc-46","type":"translationChoice","thai":"ไม่ดี","roman":"mâi dii","options":[{"text":"Where are you going?","correct":false},{"text":"Is it good?","correct":false},{"text":"Not good.","correct":true},{"text":"Good.","correct":false}],"source":"Essential Thai (Higbie), p.23","parts":["ไม่","ดี"]},{"id":"so-47","type":"sentenceOrder","prompt":"Not good.","tileUnit":"word","words":{"a":{"roman":"mâi","thai":"ไม่"},"b":{"roman":"dii","thai":"ดี"},"x0":{"thai":"มั้ย","roman":"mái"},"x1":{"thai":"ไหน","roman":"nǎi"}},"poolOrder":["a","x0","x1","b"],"correctOrder":["a","b"],"source":"Essential Thai (Higbie), p.23"},{"id":"mc-48","type":"translationChoice","thai":"ไม่","roman":"mâi","options":[{"text":"question particle: is it ___?","correct":false},{"text":"good","correct":false},{"text":"hello","correct":false},{"text":"not / no","correct":true}],"source":"Essential Thai (Higbie), p.23","parts":["ไม่"]},{"id":"rp-49","type":"reply","context":[{"speaker":"M","thai":"ไปไหนครับ","parts":["ไป","ไหน","ครับ"],"roman":"pai nǎi khráp","english":"Where are you going?"},{"speaker":"F","thai":"ฉันไปเที่ยวค่ะ","parts":["ฉัน","ไป","เที่ยว","ค่ะ"],"roman":"chán pai thîao khâ","english":"I'm going out."},{"speaker":"M","thai":"ดีมั้ยครับ","parts":["ดี","มั้ย","ครับ"],"roman":"dii mái khráp","english":"Is it good?"}],"replySpeaker":"F","thai":"ดี","roman":"dii","english":"Good.","options":[{"thai":"ไม่ดี","roman":"mâi dii","correct":false},{"thai":"สวัสดีครับ","roman":"sà-wàt-dii khráp","correct":false},{"thai":"ดี","roman":"dii","correct":true},{"thai":"ไปเที่ยว","roman":"pai thîao","correct":false}],"source":"Essential Thai (Higbie), p.23","parts":["ดี"]},{"id":"rp-51","type":"reply","context":[{"speaker":"M","thai":"สวัสดีครับ","parts":["สวัสดี","ครับ"],"roman":"sà-wàt-dii khráp","english":"Hello. (said by a man)"},{"speaker":"F","thai":"สวัสดีค่ะ","parts":["สวัสดี","ค่ะ"],"roman":"sà-wàt-dii khâ","english":"Hello. (said by a woman)"},{"speaker":"M","thai":"ไปเที่ยวดีมั้ยครับ","parts":["ไป","เที่ยว","ดี","มั้ย","ครับ"],"roman":"pai thîao dii mái khráp","english":"Is going out good?"}],"replySpeaker":"F","thai":"ไม่ดี","roman":"mâi dii","english":"Not good.","options":[{"thai":"ไปไหน","roman":"pai nǎi","correct":false},{"thai":"ไม่ดี","roman":"mâi dii","correct":true},{"thai":"ดี","roman":"dii","correct":false},{"thai":"ไปเที่ยว","roman":"pai thîao","correct":false}],"source":"Essential Thai (Higbie), p.23","parts":["ไม่","ดี"]},{"id":"sp-52","type":"speak","thai":"ไม่ดี","roman":"mâi dii","meaning":"Not good.","source":"Essential Thai (Higbie), p.23","parts":["ไม่","ดี"]},{"id":"match-53","type":"match","pairs":[{"thai":"ดี","roman":"dii","english":"good"},{"thai":"มั้ย","roman":"mái","english":"question particle: is it ___?"},{"thai":"ไม่","roman":"mâi","english":"not / no"}],"source":"Essential Thai (Higbie), p.23"}]$j$::jsonb),
